<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {Plus,Search,Pencil,X,Package,Upload,ArrowUpRight} from 'lucide-vue-next'
import {api,money} from '../api'
const categories=ref([]),records=ref([]),total=ref(0),page=ref(1),keyword=ref(''),categoryId=ref(''),loading=ref(true),error=ref(''),success=ref('')
const modal=ref(''),editing=ref(null),form=ref({}),saving=ref(false),formError=ref(''),uploading=ref(false),assets=ref([]),assetEquipment=ref(null),assetsLoading=ref(false),assetCode=ref('')
const call=(path,options={})=>api(`/admin${path}`,{...options,role:'ADMIN'})
let listVersion=0, assetsVersion=0
async function load(reset=false){if(reset)page.value=1;const current=++listVersion;loading.value=true;error.value='';try{const [c,d]=await Promise.all([call('/categories'),call('/equipment',{query:{page:page.value,pageSize:10,keyword:keyword.value.trim(),categoryId:categoryId.value}})]);if(current===listVersion){categories.value=c;records.value=d.records;total.value=d.total}}catch(e){if(current===listVersion)error.value=e.message}finally{if(current===listVersion)loading.value=false}}
function equipmentForm(item){modal.value='equipment';editing.value=item?.id||null;formError.value='';form.value=item?{categoryId:item.categoryId,name:item.name,brand:item.brand,description:item.description,image:item.image,dailyRate:item.dailyRate,deposit:item.deposit,status:item.status}:{categoryId:categories.value.find(c=>c.status===1)?.id||'',name:'',brand:'',description:'',image:'/illustrations/camera.svg',dailyRate:'',deposit:0,status:1}}
function categoryForm(item){modal.value='category';editing.value=item?.id||null;formError.value='';form.value=item?{name:item.name,sort:item.sort,status:item.status}:{name:'',sort:0,status:1}}
async function save(){saving.value=true;formError.value='';try{const name=modal.value==='category'?'categories':'equipment';await call(`/${name}${editing.value?`/${editing.value}`:''}`,{method:editing.value?'PUT':'POST',body:form.value});success.value=editing.value?'修改已保存':'创建成功';modal.value='';load()}catch(e){formError.value=e.message}finally{saving.value=false}}
async function showAssets(item){const current=++assetsVersion;assetEquipment.value=item;modal.value='assets';assets.value=[];assetsLoading.value=true;formError.value='';assetCode.value='';try{const data=await call('/assets',{query:{equipmentId:item.id}});if(current===assetsVersion)assets.value=data}catch(e){if(current===assetsVersion)formError.value=e.message}finally{if(current===assetsVersion)assetsLoading.value=false}}
async function addAsset(){saving.value=true;formError.value='';try{await call('/assets',{method:'POST',body:{equipmentId:assetEquipment.value.id,assetCode:assetCode.value.trim()}});assetCode.value='';assets.value=await call('/assets',{query:{equipmentId:assetEquipment.value.id}});load()}catch(e){formError.value=e.message}finally{saving.value=false}}
async function assetStatus(asset,event){const next=event.target.value;event.target.value=asset.status;saving.value=true;formError.value='';try{const updated=await call(`/assets/${asset.id}/status`,{method:'PUT',body:{status:next}});Object.assign(asset,updated);success.value='实物状态已更新'}catch(e){formError.value=e.message}finally{saving.value=false}}
async function upload(event){const file=event.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)){formError.value='请选择 PNG 或 JPEG 图片';event.target.value='';return}if(file.size>2*1024*1024){formError.value='图片大小不能超过 2MB';event.target.value='';return}uploading.value=true;formError.value='';try{const body=new FormData();body.append('file',file);form.value.image=await call('/upload',{method:'POST',body})}catch(e){formError.value=e.message}finally{uploading.value=false;event.target.value=''}}
function close(){if(!saving.value&&!uploading.value){assetsVersion++;modal.value=''}}
onMounted(load)
onBeforeUnmount(()=>{listVersion++;assetsVersion++})
</script>
<template><section class="wrap admin-page"><div class="page-heading"><div><span class="eyebrow">READY FOR THE NEXT SHOOT</span><h1>器材与实物</h1><p class="muted">型号定义价格，实物承载每一次租赁。</p></div><div class="action-row"><button class="button secondary small" @click="modal='categories';formError=''">分类管理</button><button class="button small" @click="equipmentForm()"><Plus :size="17"/>新增器材</button></div></div><p v-if="success" class="alert success">{{success}}<button class="icon-button" @click="success=''" aria-label="关闭"><X :size="16"/></button></p><div class="toolbar"><select v-model="categoryId" @change="load(true)" aria-label="分类筛选"><option value="">全部分类</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}{{c.status===0?'（停用）':''}}</option></select><form class="search-box" @submit.prevent="load(true)"><Search :size="17"/><input v-model="keyword" placeholder="搜索型号或品牌"><button>搜索</button></form></div><div v-if="error" class="state error">{{error}}<button class="button small" @click="load()">重试</button></div><div v-else-if="loading" class="state">正在读取器材…</div><div v-else-if="!records.length" class="state panel"><Package :size="38"/><h3>暂无器材型号</h3><p>先创建分类，再登记器材型号和实物。</p><button class="button small" @click="equipmentForm()">新增器材</button></div><div v-else class="table-wrap panel"><table><thead><tr><th>器材型号</th><th>分类</th><th>日租金 / 押金</th><th>实物数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in records" :key="item.id"><td><div class="table-product"><img :src="item.image||'/illustrations/camera.svg'" :alt="item.name" @error="$event.target.src='/illustrations/camera.svg'"><span><b>{{item.name}}</b><small>{{item.brand}}</small></span></div></td><td>{{item.categoryName}}</td><td><b>¥{{money(item.dailyRate)}}</b><small class="table-sub">押金 ¥{{money(item.deposit)}}</small></td><td>{{item.assetCount}}</td><td><span :class="['badge',item.status===1?'completed':'cancelled']">{{item.status===1?'已启用':'已停用'}}</span></td><td><div class="table-actions"><button class="text-button" @click="equipmentForm(item)"><Pencil :size="14"/>编辑</button><button class="text-button" @click="showAssets(item)"><Package :size="14"/>实物</button></div></td></tr></tbody></table></div><div v-if="total>10" class="pagination"><button :disabled="page===1||loading" @click="page--;load()">上一页</button><span>{{page}} / {{Math.ceil(total/10)}}</span><button :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section>
<Teleport to="body"><div v-if="modal" class="modal-backdrop" @click.self="close"><section class="modal" role="dialog" aria-modal="true" :aria-label="modal==='equipment'?'器材编辑':modal==='assets'?'实物管理':'分类管理'"><div class="modal-heading"><div><span class="eyebrow">CATALOG MANAGEMENT</span><h2>{{modal==='equipment'?(editing?'编辑器材':'新增器材'):modal==='assets'?'实物管理':modal==='category'?(editing?'编辑分类':'新增分类'):'分类管理'}}</h2></div><button class="icon-button" @click="close" :disabled="saving||uploading" aria-label="关闭"><X/></button></div><p v-if="formError" class="alert error" role="alert">{{formError}}</p>
<template v-if="modal==='categories'"><div class="category-row" v-for="c in categories" :key="c.id"><span><b>{{c.name}}</b><small>排序 {{c.sort}} · {{c.status===1?'启用':'停用'}}</small></span><button class="text-button" @click="categoryForm(c)">编辑<Pencil :size="14"/></button></div><button class="button full" @click="categoryForm()"><Plus :size="18"/>新增分类</button></template>
<form v-else-if="modal==='category'" @submit.prevent="save"><label>分类名称<input v-model="form.name" required maxlength="50"></label><div class="form-grid"><label>排序<input v-model.number="form.sort" type="number" required min="0" step="1"></label><label>状态<select v-model="form.status"><option :value="1">启用</option><option :value="0">停用</option></select></label></div><button class="button full" :disabled="saving">{{saving?'保存中…':'保存分类'}}</button></form>
<form v-else-if="modal==='equipment'" @submit.prevent="save"><label>器材名称<input v-model="form.name" required maxlength="100" placeholder="例如：Sony A7 IV 全画幅相机"></label><div class="form-grid"><label>所属分类<select v-model="form.categoryId" required><option value="" disabled>请选择分类</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}{{c.status===0?'（已停用）':''}}</option></select></label><label>品牌<input v-model="form.brand" maxlength="50" placeholder="例如：SONY"></label><label>日租金（元）<input v-model.number="form.dailyRate" type="number" min="0.01" max="99999999.99" step="0.01" required></label><label>押金（元）<input v-model.number="form.deposit" type="number" min="0" max="99999999.99" step="0.01" required></label></div><label>型号介绍<textarea v-model="form.description" maxlength="2000" rows="3" placeholder="适用场景、规格及配件说明"/></label><div class="upload-row"><img :src="form.image||'/illustrations/camera.svg'" alt="器材图片预览"><label class="button secondary small upload-button"><Upload :size="16"/>{{uploading?'上传中…':'上传器材图片'}}<input type="file" accept="image/jpeg,image/png" @change="upload" :disabled="uploading"></label><small class="muted">支持 PNG / JPEG，最大 2MB</small></div><label>展示状态<select v-model="form.status"><option :value="1">启用</option><option :value="0">停用</option></select></label><p class="hint">新建型号后，还需登记可出租的实物。型号本身不代表可租库存。</p><button class="button full" :disabled="saving||uploading">{{saving?'保存中…':'保存器材'}}</button></form>
<template v-else-if="modal==='assets'"><h3>{{assetEquipment.name}}</h3><p class="hint">每件实物具有唯一编号。有未完成预约时，不能将实物送修或停用。</p><form class="asset-add" @submit.prevent="addAsset"><input v-model="assetCode" placeholder="输入实物编号，例如 GH-CAM-001" maxlength="64" required :disabled="saving"><button class="button small" :disabled="saving"><Plus :size="16"/>登记</button></form><p v-if="assetsLoading" class="state">读取中…</p><div v-else-if="!assets.length" class="state">尚未登记实物</div><div v-for="a in assets" :key="a.id" class="asset-row"><span><b>{{a.assetCode}}</b><small>{{a.createdAt}}</small></span><select :value="a.status" @change="assetStatus(a,$event)" :disabled="saving" :aria-label="`${a.assetCode} 状态`"><option value="READY">可出租</option><option value="MAINTENANCE">维修中</option><option value="RETIRED">已停用</option></select></div></template>
</section></div></Teleport></template>
